SELECT pp.id AS paper_position_id, ts.id, ts.symbol, ts.interval_code, ts.candle_open_time, ts.generated_at, ts.decision, ts.original_decision, ts.trend_score, ts.confluence_status, ts.confluence_higher_interval, ts.confluence_higher_decision, ts.data_quality_valid, ts.signal_mode, ts.latest_price FROM crypto_ai.trade_signal ts JOIN crypto_ai.paper_position pp ON ts.symbol = pp.symbol AND ts.generated_at BETWEEN pp.closed_at - INTERVAL 70 MINUTE AND pp.closed_at WHERE pp.id IN (182,172,162,158,143,137) AND (ts.interval_code IN ('5m','1h') OR ts.generated_at >= pp.closed_at - INTERVAL 3 MINUTE) ORDER BY pp.id, ts.generated_at LIMIT 160